def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    last_me = me[-1]
    last_op = op[-1]

    opp_d = 0
    for x in op:
        if x == 'D':
            opp_d += 1
    opp_c = n - opp_d

    recent_len = min(10, n)
    r_op = op[n - recent_len:]
    r_opp_c = 0
    for x in r_op:
        if x == 'C':
            r_opp_c += 1

    op_d_streak = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        op_d_streak += 1
        i -= 1

    my_c_streak = 0
    i = n - 1
    while i >= 0 and me[i] == 'C':
        my_c_streak += 1
        i -= 1

    resp_c = 0
    resp_d = 0
    after_c_t = 0
    after_c_d = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'C':
                resp_c += 1
            else:
                resp_d += 1
        if me[i] == 'C':
            after_c_t += 1
            if op[i + 1] == 'D':
                after_c_d += 1

    if n >= 20:
        base = ['D', 'D', 'C', 'C', 'C']
        last10 = op[n - 10:]
        for s in range(5):
            ok = True
            for j in range(10):
                if last10[j] != base[(j + s) % 5]:
                    ok = False
                    break
            if ok:
                return 'D'

    if opp_c == 0 and n >= 5:
        return 'D'

    if r_opp_c == 0 and n >= 10 and op_d_streak >= 10:
        return 'D'

    if last_op == 'D':
        if n >= 2 and me[-2] == 'D':
            return 'C'
        if my_c_streak >= 5:
            return 'D'
        if op_d_streak >= 8 and my_c_streak >= 3:
            return 'D'
        return 'C'

    if n >= 16 and resp_c >= 1 and resp_d == 0 and r_opp_c >= 6:
        return 'D'

    if (last_me == 'C' and n >= 22 and after_c_t >= 16 and after_c_d >= 5 and
        after_c_d * 4 >= after_c_t and after_c_d * 3 <= after_c_t * 2 and
        opp_c * 2 >= n and r_opp_c >= 5):
        return 'D'

    if (resp_c == 0 and resp_d == 0 and n >= 15 and last_me == 'C' and
        last_op == 'C' and opp_c >= n - 5):
        if not (n >= 15 and op[n - 5:n] == ['D', 'D', 'C', 'C', 'C']):
            return 'D'

    return 'C'
